use std::collections::HashSet;
use std::hash::Hash;

/// Remove duplicates from `nums`, returning a new Vec containing the elements of `nums`
/// with duplicates removed. The order of first occurrence is preserved.
///
/// Postconditions:
/// 1) The output vector contains no duplicates.
/// 2) The set of elements in the output equals the set of elements in `nums`.
pub fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut res = Vec::new();
    for &num in &nums {
        if seen.insert(num) {
            // insert returns true if num was not already present
            res.push(num);
        }
    }
    res
}

